import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matvec_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec(torch::Tensor A, torch::Tensor B);
"""

matvec_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
  #include <cuda_pipeline.h>
using namespace cute;
// C = A * B with A: (M, K) row-major, B: (K, 1)
// Skinny-N GEMV tiling: each CTA owns a small tile of Rows output rows and one
// contiguous K-chunk. The B fragment for a K-tile is loaded once per thread and
// reused across all Rows rows in registers, cutting B traffic by Rows while A
// remains a streaming float4 load. Split-K partial sums are still combined with
// atomicAdd when gridDim.y > 1.
template <int Threads, int Vec, int Rows>
__global__ __launch_bounds__(Threads)
void matvec_cute_kernel(const float* __restrict__ A,
                        const float* __restrict__ B,
                        float* __restrict__ C,
                        int M, int K, int chunk)
{
  const int mt  = blockIdx.x;
  const int tid = threadIdx.x;
  constexpr int TileK = Threads * Vec;
  constexpr int RPB   = Rows;
  const int m0   = mt * RPB;
  const int rows = min(RPB, M - m0);
  const int k0   = blockIdx.y * chunk;
  const int k1   = min(K, k0 + chunk);
  const int len  = k1 - k0;
  if (len <= 0 || rows <= 0) return;
  const int R    = len / TileK;
  const int main = R * TileK;
  const float* abase = A + (long long)m0 * (long long)K + k0;
  const float* bptr  = B + k0;
  Tensor gA = make_tensor(make_gmem_ptr(abase),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R, Int<RPB>{}),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}, (long long)K));
  Tensor gB = make_tensor(make_gmem_ptr(bptr),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));
  Tensor tBgB = gB(_, tid, _);
  float acc[RPB];
  #pragma unroll
  for (int r = 0; r < RPB; ++r) acc[r] = 0.f;
  if constexpr (Vec == 8) {
    Tensor tBgB4 = recast<float4>(tBgB);
    for (int j = 0; j < R; ++j) {
      const float4 b0 = tBgB4(0, j);
      const float4 b1 = tBgB4(1, j);
      #pragma unroll
      for (int r = 0; r < RPB; ++r) {
        if (r < rows) {
          Tensor tAgA4 = recast<float4>(gA(_, tid, _, r));
          const float4 a0 = tAgA4(0, j);
          const float4 a1 = tAgA4(1, j);
          float dot = a0.x * b0.x + a0.y * b0.y + a0.z * b0.z + a0.w * b0.w;
          dot += a1.x * b1.x + a1.y * b1.y + a1.z * b1.z + a1.w * b1.w;
          acc[r] += dot;
        }
      }
    }
  } else if constexpr (Vec == 4) {
    Tensor tBgB4 = recast<float4>(tBgB);
    for (int j = 0; j < R; ++j) {
      const float4 b = tBgB4(j);
      #pragma unroll
      for (int r = 0; r < RPB; ++r) {
        if (r < rows) {
          Tensor tAgA4 = recast<float4>(gA(_, tid, _, r));
          const float4 a = tAgA4(j);
          acc[r] += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
        }
      }
    }
  } else {
    for (int j = 0; j < R; ++j) {
      #pragma unroll
      for (int r = 0; r < RPB; ++r) {
        if (r < rows) {
          Tensor tAgA = gA(_, tid, _, r);
          float dot = 0.f;
          CUTE_UNROLL
          for (int v = 0; v < Vec; ++v) dot += tAgA(v, j) * tBgB(v, j);
          acc[r] += dot;
        }
      }
    }
  }
  for (int e = main + tid; e < len; e += Threads) {
    const float bv = bptr[e];
    const float* atail = abase + e;
    #pragma unroll
    for (int r = 0; r < RPB; ++r) {
      if (r < rows) acc[r] += atail[(long long)r * (long long)K] * bv;
    }
  }
  __shared__ float smem[Threads / 32];
  const int lane = tid & 31;
  const int warp = tid >> 5;
  #pragma unroll
  for (int r = 0; r < RPB; ++r) {
    if (r < rows) {
      float v = acc[r];
      #pragma unroll
      for (int off = 16; off > 0; off >>= 1) {
        v += __shfl_down_sync(0xffffffffu, v, off);
      }
      if (lane == 0) smem[warp] = v;
      __syncthreads();
      if (warp == 0) {
        constexpr int NW = Threads / 32;
        float s = (lane < NW) ? smem[lane] : 0.f;
        #pragma unroll
        for (int off = 16; off > 0; off >>= 1) {
          s += __shfl_down_sync(0xffffffffu, s, off);
        }
        if (lane == 0) {
          const int m = m0 + r;
          if (gridDim.y == 1) C[m] = s;
          else atomicAdd(&C[m], s);
        }
      }
      __syncthreads();
    }
  }
}
torch::Tensor matvec(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
  TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be (K, 1)");
  int64_t M = A.size(0);
  int64_t K = A.size(1);
  TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  constexpr int Threads = 256;
  constexpr int RowsPerCTA = 8;
  const int vec           = (K % 8 == 0) ? 8 : ((K % 4 == 0) ? 4 : 1);
  const int64_t tileK     = (int64_t)Threads * vec;
  const int64_t rowTiles  = (M + RowsPerCTA - 1) / RowsPerCTA;
  int wave = 0;
  {
    int dev = 0;
    cudaGetDevice(&dev);
    int smCount = 0;
    cudaDeviceGetAttribute(&smCount, cudaDevAttrMultiProcessorCount, dev);
    int blocksPerSM = 0;
    cudaError_t occErr;
    if (vec == 8) {
      occErr = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
          &blocksPerSM, matvec_cute_kernel<Threads, 8, RowsPerCTA>, Threads, 0);
    } else if (vec == 4) {
      occErr = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
          &blocksPerSM, matvec_cute_kernel<Threads, 4, RowsPerCTA>, Threads, 0);
    } else {
      occErr = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
          &blocksPerSM, matvec_cute_kernel<Threads, 1, RowsPerCTA>, Threads, 0);
    }
    if (occErr != cudaSuccess || blocksPerSM < 1) blocksPerSM = 1;
    wave = smCount * blocksPerSM;
  }
  int64_t splitBlocks = 1;
  int64_t totalTiles  = (K + tileK - 1) / tileK;
  if (wave > 0 && totalTiles >= 8) {
    int64_t bestS = 1, bestWaste = ((int64_t)1 << 62);
    for (int64_t s = 1; s <= 8; ++s) {
      const int64_t blocks = rowTiles * s;
      const int64_t waves  = (blocks + wave - 1) / wave;
      const int64_t waste  = waves * wave - blocks;
      if (waste == 0) { bestS = s; break; }
      if (waste < bestWaste) { bestWaste = waste; bestS = s; }
    }
    splitBlocks = bestS;
  }
  const int64_t tilesPerSplit = (totalTiles + splitBlocks - 1) / splitBlocks;
  const int64_t chunk         = tilesPerSplit * tileK;
  splitBlocks = (K + chunk - 1) / chunk;
  auto C = (splitBlocks > 1) ? torch::zeros({M, 1}, A.options())
                             : torch::empty({M, 1}, A.options());
  dim3 block(Threads);
  dim3 grid((unsigned)rowTiles, (unsigned)splitBlocks);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (vec == 8) {
    matvec_cute_kernel<Threads, 8, RowsPerCTA><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K, (int)chunk);
  } else if (vec == 4) {
    matvec_cute_kernel<Threads, 4, RowsPerCTA><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K, (int)chunk);
  } else {
    matvec_cute_kernel<Threads, 1, RowsPerCTA><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)K, (int)chunk);
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matvec launch failed: ",
              cudaGetErrorString(err));
  return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=matvec_cpp_decl,
    cuda_sources=matvec_cuda_src,
    functions=["matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a single
    custom CuTe CUDA kernel (cooperative tiled reduction over K).
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        if not A.is_cuda:
            A = A.cuda()
            B = B.cuda()
            return self._ext.matvec(A, B).cpu()
        if A.dtype != torch.float32:
            return torch.matmul(A, B)
        return self._ext.matvec(A, B)

