  const int k0  = blockIdx.y * chunk;
  const int k1  = min(K, k0 + chunk);
  const int len = k1 - k0;
  if (len <= 0) return;
  const int R    = len / TileK;   // number of full tiles in this chunk
  const int main = R * TileK;     // elements covered by full tiles
  const float* arow = A + (long long)m * (long long)K + k0;
  const float* bptr = B + k0;
  // CuTe views of the chunk of the row of A and of B as (Vec, Threads, R)
  // so that thread `tid` owns `Vec` contiguous elements per tile.
  Tensor gA = make_tensor(make_gmem_ptr(arow),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));
  Tensor gB = make_tensor(make_gmem_ptr(bptr),
                          make_shape(Int<Vec>{}, Int<Threads>{}, R),
                          make_stride(Int<1>{}, Int<Vec>{}, Int<TileK>{}));
  Tensor tAgA = gA(_, tid, _);   // (Vec, R) : (1, TileK)
  Tensor tBgB = gB(_, tid, _);   // (Vec, R) : (1, TileK)
  float acc0 = 0.f, acc1 = 0.f, acc2 = 0.f, acc3 = 0.f;
  float acc4 = 0.f, acc5 = 0.f, acc6 = 0.f, acc7 = 0.f;
  if constexpr (Vec == 8) {
    // Direct streaming vectorized loads instead of cp.async smem staging.
    // The kernel is DRAM-bound (96% DRAM throughput) and its theoretical
    // occupancy was capped at 50% by the 32KB static shared-memory
    // footprint of the double-buffered pipeline. Removing smem staging
    // lifts the occupancy limit while keeping the same float4 streaming
    // volume from DRAM.
    Tensor tAgA4 = recast<float4>(tAgA);   // (2, R) of float4
    Tensor tBgB4 = recast<float4>(tBgB);   // (2, R) of float4
    for (int j = 0; j < R; ++j) {
      float4 a0 = tAgA4(0, j);
      float4 a1 = tAgA4(1, j);
      float4 b0 = tBgB4(0, j);
      float4 b1 = tBgB4(1, j);
      acc0 += a0.x * b0.x;
      acc1 += a0.y * b0.y;
      acc2 += a0.z * b0.z;
      acc3 += a0.w * b0.w;
      acc4 += a1.x * b1.x;
      acc5 += a1.y * b1.y;
      acc6 += a1.z * b1.z;
      acc7 += a1.w * b1.w;
    }
  } else if constexpr (Vec == 4) {
    Tensor tAgA4 = recast<float4>(tAgA);   // (R) of float4
    Tensor tBgB4 = recast<float4>(tBgB);   // (R) of float4
    for (int j = 0; j < R; ++j) {
      float4 a = tAgA4(j);
      float4 b = tBgB4(j);
      acc0 += a.x * b.x;
      acc1 += a.y * b.y;
      acc2 += a.z * b.z;
      acc3 += a.w * b.w;
    }
  } else {
    for (int j = 0; j < R; ++j) {
      CUTE_UNROLL
      for (int v = 0; v < Vec; ++v) {
        acc0 += tAgA(v, j) * tBgB(v, j);
      }
    }
  }
  float acc = (acc0 + acc1) + (acc2 + acc3) + (acc4 + acc5) + (acc6 + acc7);
  // Tail elements if this chunk's length is not a multiple of Threads*Vec
  for (int e = main + tid; e < len; e += Threads) {
    acc += arow[e] * bptr[e];
  }
  // Block-wide reduction (warp shuffles + shared memory)
  __shared__ float smem[Threads / 32];
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    acc += __shfl_down_sync(0xffffffffu, acc, off);
  }
  const int lane = tid & 31;
  const int warp = tid >> 5;
  if (lane == 0) smem[warp] = acc;
  __syncthreads();
  if (warp == 0) {
    constexpr int NW = Threads / 32;
    float v = (lane < NW) ? smem[lane] : 0.f;
    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
      v += __shfl_down_sync(0xffffffffu, v, off);
    }
    if (lane == 0) {
      if (gridDim.y == 1) C[m] = v;   // no split-K: single owner block
      else atomicAdd(&C[m], v);
    }
  }
}
